def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    centers = []
    # Each motif is a four-point diamond around an empty center.
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (grid[r - 1][c] == 2 and grid[r + 1][c] == 2
                    and grid[r][c - 1] == 2 and grid[r][c + 1] == 2):
                centers.append((r, c))

    arms = ((-1, 0), (1, 0), (0, -1), (0, 1))
    for i, (r1, c1) in enumerate(centers):
        for r2, c2 in centers[i + 1:]:
            # Extend only the tips that face the other diamond.
            if r1 == r2 and c1 < c2:
                p1, p2 = (r1, c1 + 1), (r2, c2 - 1)
                for c in range(p1[1] + 1, p2[1]):
                    if out[r1][c] == 0:
                        out[r1][c] = 1
            elif c1 == c2 and r1 < r2:
                p1, p2 = (r1 + 1, c1), (r2 - 1, c2)
                for r in range(p1[0] + 1, p2[0]):
                    if out[r][c1] == 0:
                        out[r][c1] = 1
    return out
